#!/usr/bin/env node
/**
 * 日报生成脚本 (Node.js版本)
 * 生成 Markdown 和 Word 格式的日报
 */

const fs = require('fs');
const path = require('path');

const OUTPUT_DIR = path.join(process.env.HOME, 'DailyReports');

function loadCrawlResults(filePath) {
  const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
  return data.results || [];
}

function categorizeNews(newsList) {
  const categories = {
    "国家部委": [],
    "省级政策": [],
    "市级政策": [],
    "区级政策": [],
    "行业协会": [],
    "项目申报": [],
    "其他": []
  };

  for (const news of newsList) {
    const category = news.category || '其他';

    if (category.includes('国家') || category.includes('中华人民共和国')) {
      categories["国家部委"].push(news);
    } else if (category.includes('省级') || category.includes('福建省')) {
      categories["省级政策"].push(news);
    } else if (category.includes('市级') || category.includes('厦门市')) {
      categories["市级政策"].push(news);
    } else if (category.includes('区级') || category.includes('思明') || category.includes('集美')) {
      categories["区级政策"].push(news);
    } else if (category.includes('协会') || category.includes('行业')) {
      categories["行业协会"].push(news);
    } else if (category.includes('申报') || category.includes('项目')) {
      categories["项目申报"].push(news);
    } else {
      categories["其他"].push(news);
    }
  }

  // 移除空类别
  return Object.fromEntries(Object.entries(categories).filter(([k, v]) => v.length > 0));
}

function generateMarkdown(newsList, dateStr) {
  const total = newsList.length;
  const categorized = categorizeNews(newsList);
  const categoryCount = Object.keys(categorized).length;

  let md = `# 政府网站新闻政策日报

**报告日期**: ${dateStr}
**数据来源**: 17个政府网站
**生成时间**: ${new Date().toLocaleString('zh-CN')}

---

## 概览

| 统计项 | 数量 |
|--------|------|
| 监控网站数 | 17 |
| 新增新闻/政策 | ${total} |
| 分类数量 | ${categoryCount} |

---

`;

  // 如果没有数据，添加说明
  if (total === 0) {
    md += `## 数据抓取说明

本次抓取未能获取到新闻数据，主要原因包括：

1. **网站结构变化**: 部分政府网站近期进行了改版，DOM结构发生变化
2. **动态加载机制**: 部分网站使用 JavaScript 动态加载内容，需要更复杂的处理
3. **访问限制**: 部分网站可能有访问频率限制或需要特定请求头
4. **网络连接**: 厦门市建设局网站 (js.xm.gov.cn) 域名解析失败

### 已尝试的抓取网站

本次共尝试抓取 17 个政府网站：

- 国家部委: 科技部、工信部、发改委、自然资源部
- 省级: 福建省科技厅、福建省教育厅
- 市级: 厦门市人社局、发改委、科技局、工信局、建设局、数据管理局、总工会
- 区级: 思明区科信局
- 开发区: 火炬高新区
- 行业协会: 市软件协会、中小企业服务中心

### 后续改进建议

1. 更新各网站的 CSS 选择器配置
2. 增加对动态加载网站的支持（如使用 waitForFunction 等待内容加载）
3. 添加更多备用选择器策略
4. 增加请求头伪装和 User-Agent 轮换
5. 考虑使用 RSS 源或 API 接口（如有提供）

---

`;
  } else {
    // 按类别输出
    for (const [category, items] of Object.entries(categorized)) {
      md += `## ${category} (${items.length}条)\n\n`;

      for (const item of items) {
        md += `### ${item.title}\n\n`;
        md += `- **来源**: ${item.site_name}\n`;
        md += `- **日期**: ${item.date}\n`;
        md += `- **链接**: ${item.url}\n`;
        md += `- **摘要**: ${item.summary}\n\n`;
      }

      md += "---\n\n";
    }
  }

  // 页脚
  md += `---\n\n`;
  md += `**报告生成时间**: ${new Date().toLocaleString('zh-CN')}\n`;
  md += `**下次生成时间**: 明天 06:45\n\n`;
  md += `---\n\n`;
  md += `*本报告由 OpenClaw Daily News Crawler 自动生成*\n`;

  return md;
}

function generateSimpleWordContent(mdContent) {
  // 将 Markdown 转换为纯文本格式（用于 Word）
  let text = mdContent
    .replace(/^# (.*$)/gm, '$1\n' + '='.repeat(50))
    .replace(/^## (.*$)/gm, '\n$1\n' + '-'.repeat(40))
    .replace(/^### (.*$)/gm, '\n  $1')
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/\*(.*?)\*/g, '$1')
    .replace(/^---$/gm, '\n' + '_'.repeat(50) + '\n')
    .replace(/\|/g, ' | ')
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1 ($2)');

  return text;
}

function main() {
  // 获取输入文件
  let crawlResultFile;
  if (process.argv.length > 2) {
    crawlResultFile = process.argv[2];
  } else {
    // 查找最新的抓取结果文件
    const resultFiles = fs.readdirSync(OUTPUT_DIR)
      .filter(f => f.startsWith('crawl_result_') && f.endsWith('.json'))
      .map(f => ({ name: f, time: fs.statSync(path.join(OUTPUT_DIR, f)).mtime }))
      .sort((a, b) => b.time - a.time);

    if (resultFiles.length > 0) {
      crawlResultFile = path.join(OUTPUT_DIR, resultFiles[0].name);
    } else {
      console.log('[ERROR] 未找到抓取结果文件');
      process.exit(1);
    }
  }

  const dateStr = new Date().toISOString().split('T')[0];

  console.log(`[INFO] 加载抓取结果: ${crawlResultFile}`);
  const newsList = loadCrawlResults(crawlResultFile);
  console.log(`[INFO] 共 ${newsList.length} 条新闻`);

  // 生成 Markdown
  console.log('[INFO] 生成 Markdown 文档...');
  const mdContent = generateMarkdown(newsList, dateStr);

  // 确保输出目录存在
  const mdDir = path.join(OUTPUT_DIR, 'md');
  const docDir = path.join(OUTPUT_DIR, 'doc');
  if (!fs.existsSync(mdDir)) fs.mkdirSync(mdDir, { recursive: true });
  if (!fs.existsSync(docDir)) fs.mkdirSync(docDir, { recursive: true });

  const mdFile = path.join(mdDir, `${dateStr}-日报.md`);
  fs.writeFileSync(mdFile, mdContent, 'utf-8');
  console.log(`[INFO] Markdown 已保存: ${mdFile}`);

  // 生成纯文本版本（作为 Word 的替代）
  console.log('[INFO] 生成 Word 文档 (纯文本格式)...');
  const wordContent = generateSimpleWordContent(mdContent);
  const docFile = path.join(docDir, `${dateStr}-日报.txt`);
  fs.writeFileSync(docFile, wordContent, 'utf-8');
  console.log(`[INFO] Word 文本版本已保存: ${docFile}`);

  // 输出摘要
  const categorized = categorizeNews(newsList);
  console.log('\n' + '='.repeat(60));
  console.log('[INFO] 日报生成完成');
  console.log(`[INFO] 总新闻数: ${newsList.length}`);
  console.log(`[INFO] 分类数量: ${Object.keys(categorized).length}`);
  for (const [cat, items] of Object.entries(categorized)) {
    console.log(`  - ${cat}: ${items.length}条`);
  }
  console.log('='.repeat(60));
}

main();

